import { createHash } from "node:crypto";

export const contentHash = (value) =>
  createHash("sha256").update(value).digest("hex");
export const companionPrefix =
  "```mermaid\n%% Generated by ArcShape diagram bundle ";

export function companionContent(mermaid, source) {
  return (
    companionPrefix +
    JSON.stringify({
      source: contentHash(source),
      content: contentHash(mermaid),
    }) +
    "\n" +
    mermaid +
    "```\n"
  );
}

export function isGeneratedCompanion(raw) {
  return (
    /^```mermaid\n%% Generated by ArcShape diagram bundle \{"source":"[a-f0-9]{64}","content":"[a-f0-9]{64}"\}\n[\s\S]*\n```\n?$/.test(
      raw,
    ) && (raw.match(/^```/gm) ?? []).length === 2
  );
}

export function unmodifiedCompanion(raw) {
  if (!isGeneratedCompanion(raw)) return false;
  const end = raw.indexOf("\n", companionPrefix.length);
  const header = JSON.parse(raw.slice(companionPrefix.length, end));
  return (
    contentHash(raw.slice(end + 1).replace(/```\n?$/, "")) === header.content
  );
}
